// reviewsData.ts
export interface ReviewData {
    reviewer: string;
    lessons: number;
    quote: string;
  }

 export const reviews: ReviewData[] = [
    {
        reviewer: "John Doe",
        lessons: 10,
        quote: "Great tutor! Highly recommended."
    },
    {
        reviewer: "Jane Smith",
        lessons: 8,
        quote: "Oliver is very knowledgeable and patient."
    },
    {
        reviewer: "Emma Brown",
        lessons: 15,
        quote: "My skills have improved tremendously thanks to Oliver's guidance."
    },
    {
        reviewer: "Mar P.",
        lessons: 18,
        quote: "Oliver is super knowledeage and a great teacher. He is great for anything relating to Machine Learning or Data Science."   
    },
    {
        reviewer: "Hannah P.",
        lessons: 7,
        quote: "I have learned so much working on Data Science course material with Oliver for 2 semesters now. He is patient and makes complicated material easy to understand.",
    },
  ];

  export const colors = ['#A7FFD5', '#C5ABFF', '#FFC8FF', '#E595E5', '#A7FFD5', '#FFC8FF', '#C5ABFF', '#E595E5', '#A7FFD5', '#C5ABFF', '#FFC8FF'];

  export const getRandomColor = () => {
    return colors[Math.floor(Math.random() * colors.length)];
  };

  export const sliderSettings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 3,
    slidesToScroll: 1,
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 3,
          slidesToScroll: 1,
          infinite: true,
          dots: true
        }
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 2,
          slidesToScroll: 1,
          initialSlide: 2
        }
      },
      {
        breakpoint: 480,
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1
        }
      }
    ]
  };
